/* the GSearchControl CSS Classes
 * .gsc-control: the primary class of the control
 */
.gsc-control {
  width: 300px;
}

.gsc-control div {
  position: static;
}

.gsc-control-cse,
.gsc-control-cse .gsc-table-result {
  font-size: 14px;
  line-height: 22px;
  width: auto;
}

.gsc-control-cse {
  padding: 16px 0;
}

.gsc-control-wrapper-cse {
  width: 100%;
}

/* control inputs
 * .gsc-search-box: the container that hosts the text input area
 * .gsc-input: the text input area
 * .gsc-keeper: the save link below savable results
 */
form.gsc-search-box {
  max-width: 652px;
  font-size: 14px;
  margin: 0 24px;
}

/*
 * This table contains the input element as well as the search button
 * Note that the search button column is fixed width, designed to hold the
 * button div's background image
 */
table.gsc-search-box {
  border-style: none;
  border-width: 0;
  border-spacing: 0 0;
  width: 100%;
}

table.gsc-search-box td {
  vertical-align: middle;
}

.gsc-search-button {
  width: 1%;
}

.gsc-search-button-v2 svg {
  fill: #fff;
}

/* Firefox button fix */
button::-moz-focus-inner {
  padding: 0;
  border: 0;
}

.gsc-clear-button {
  width: 14px;
}

.gsc-branding {
  display: -ms-flexbox;
  display: flex;
  justify-content: flex-end;
  padding: 4px;
}

.gsc-branding-text,
.gcsc-branding-text {
  vertical-align: top;
  padding-bottom: 2px;
  text-align: right;
  font-size: 11px;
  margin-right: 2px;
  color: #666;
}

.gsc-branding-text:first-child,
.gcsc-branding-text:first-child {
  flex-grow: 1;
}

.gsc-branding-img-noclear,
.gcsc-branding-img-noclear {
  width: 51px;
  vertical-align: bottom;
}

.gsc-branding-img,
.gcsc-branding-img {
  width: 65px;
  vertical-align: bottom;
}

.gsc-branding-youtube .gsc-branding-img-noclear {
  width: 55px;
}

.gsc-branding-youtube .gsc-branding-img {
  width: 69px;
}

.gsc-branding-vertical .gsc-branding-text .gsc-branding-text {
  margin-right: 0;
  text-align: center;
}

.gsc-branding-vertical .gsc-branding-img-noclear {
  text-align: center;
}

.gsc-branding-img,
.gsc-branding-img-noclear,
.gcsc-branding-img,
.gcsc-branding-img-noclear {
  position: relative;
  top: -1px;
  padding-left: 2px;
  padding-right: 2px;
}

.gsc-branding-img,
.gsc-branding-img-noclear,
.gcsc-branding-img,
.gcsc-branding-img-noclear {
  margin: 0 0 0 0;
  padding-top: 0;
  padding-bottom: 0;
  border: none;
  display: inline;
}

.gcsc-branding-text {
  white-space: nowrap;
}

.gcsc-branding-text {
  margin: 0 2px;
}

.gcsc-branding-img-noclear {
  width: auto;
}

.gsc-branding-clickable {
  cursor: pointer;
}

.gsc-search-button {
  margin-left: 2px;
}

.gsc-clear-button {
  display: inline;
  text-align: right;
  margin-left: 4px;
  margin-right: 4px;
  padding-left: 10px;
  background-repeat: no-repeat;
  background-position: center center;
  background-image: url('//www.google.com/cse/static/css/v2/clear.png');
  cursor: pointer;
}

.gsc-clear-button:hover {
  background-image: url('//www.google.com/cse/static/css/v2/clear-hover.png');
}

.gsc-search-box-tools .gsc-clear-button {
  display: none;
}

.gsc-results-close-btn {
  background-image: url("//www.google.com/images/nav_logo114.png");
  background-repeat: no-repeat;
  background-position: -140px -230px;
  float: right;
  display: none;
  opacity: 0;
  height: 12px;
  width: 12px;
  position: absolute !important;
  top: 20px;
  right: 20px;
  cursor: pointer;
}

.gsc-results-close-btn-visible {
  display: block;
  opacity: 1;
}

.gsc-results-wrapper-overlay {
  border: none;
  margin: auto;
  border-radius: 1px;
  overflow: auto;
  height: 80%;
  -webkit-box-shadow: 0 3px 10px rgba(34, 25, 25, 0.4);
  -moz-box-shadow: 0 3px 10px rgba(34, 25, 25, 0.4);
  -ms-box-shadow: 0 3px 10px rgba(34, 25, 25, 0.4);
  -o-box-shadow: 0 3px 10px rgba(34, 25, 25, 0.4);
  box-shadow: 0 3px 10px rgba(34, 25, 25, 0.4);
  border-collapse: separate;
  background: white;
  padding: 30px;
  width: 70%;
  position: fixed !important;
  top: 5%;
  left: 12%;
  opacity: 0;
  z-index: 100002;
  visibility: hidden;
  -webkit-transition: all 0.25s linear;
  -moz-transition: all 0.25s linear;
  -ms-transition: all 0.25s linear;
  -o-transition: all 0.25s linear;
  transition: all 0.25s linear;
  /* For IE 8 */
  -ms-filter: "progid:DXImageTransform.Microsoft.Shadow(Strength=7, Direction=135, Color='#888888')";
  /* For IE 5.5 - 7 */
  filter: progid:DXImageTransform.Microsoft.Shadow(Strength=7, Direction=135, Color='#888888');

}

.gsc-results-wrapper-visible {
  opacity: 1 !important;
  visibility: visible !important;
}

.gsc-modal-background-image {
  position: fixed !important;
  top: 0;
  left: 0;
  height: 130%;
  width: 100%;
  z-index: 100001;
  background-color: white;
  opacity: 0;
  -ms-filter: "alpha(opacity=0)";
  filter: alpha(opacity=0);
  display: none;
  -webkit-transition: all 0.25s linear;
  -moz-transition: all 0.25s linear;
  -ms-transition: all 0.25s linear;
  -o-transition: all 0.25s linear;
  transition: all 0.25s linear;
}

.gsc-modal-background-image-visible {
  opacity: 0.8;
  -ms-filter: "alpha(opacity=80)";
  filter: alpha(opacity=80);
  display: block;
}

.gsc-overflow-hidden {
  overflow: hidden;
}

table.gsc-input {
    table-layout: fixed;
}

/*
 * Given that this is sitting in a variable width table cell, the idea is
 * for it to consume the entire cell. The adjacent cell contains the search
 * button and that is a fixed width cell.
 */
input.gsc-input {
  padding: 1px 6px;
  border: 1px solid #ddd;
}

.gsc-search-box .gsc-input>input:hover,
.gsc-input-box-hover {
  border: 1px solid #b9b9b9;
  border-top-color: #a0a0a0;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .1);
  outline: none;
}

.gsc-keeper {
  color: #36c;
  text-decoration: underline;
  font-size: 14px;
  cursor: pointer;
  font-weight: normal;

  padding-left: 16px;
  background-repeat: no-repeat;
  background-position: 1px 3px;
  background-image: url('//www.google.com/cse/static/css/blue_check.gif');
}

/* tabbed mode of search control
 * .gsc-positioningWrapper: wrapper for absolute positioning of gradient
 * .gsc-tabsArea: the box containing all of the tabs
 * .gsc-tabsAreaInvisible: same as above, but this is the state when search has been cleared
 * .gsc-tabHeader: an individual tab
 * .gsc-tabHeader.gsc-tabhActive: the active tab
 * .gsc-tabHeader.gsc-tabhInactive: an inactive tab
 * .gsc-tabData: the data area/box containing results and header data for each tab
 * .gsc-tabData.gsc-tabdActive: the data area for the active tab
 * .gsc-tabData.gsc-tabdInactive: the data area for inactive tabs
 */
.gsc-positioningWrapper {
  position: relative;
}

.gsc-tabsArea {
  clear: both;
  border-bottom: 1px solid #dfe1e5;
  margin-top: 16px;
}

.gsc-tabsArea .gs-spacer,
.gsc-refinementsArea .gs-spacer {
  display: none;
}

.gsc-tabsAreaInvisible,
.gsc-refinementsAreaInvisible,
.gsc-refinementBlockInvisible {
  display: none;
}

.gsc-tabHeader {
  border: none;
  font-size: 14px;
  line-height: 20px;
  padding: 14px 0;
  margin: 0 24px;
  text-align: center;
}

.gsc-tabHeader.gsc-tabhInactive {
  cursor: pointer;
}

.gsc-tabData.gsc-tabdActive {
  display: block;
}

.gsc-tabData.gsc-tabdInactive {
  display: none;
}

/* gsc-resultsbox-invisible is preferred over gsc-tabdActive */
.gsc-tabData.gsc-tabdActive.gsc-resultsbox-invisible {
  display: none;
}

.gsc-refinementsArea {
  border-bottom: 1px solid #dfe1e5;
  clear: both;
  margin-top: 16px;
  padding-left: 16px;
