/* Image Search */
.gs-ellipsis {
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  -o-text-overflow: ellipsis;
  -ms-text-overflow: ellipsis;
  white-space: nowrap;
}

.gsc-imageResult-column {
  margin-right: 70px;
}

.gs-imageResult {
  break-inside: avoid;
  overflow: hidden;
}

.gs-imageResult .gs-image-box {
  position: relative;
}

.gs-imageResult .gs-text-box {
  color: #999;
  height: 4em;
}

/* No padding for image result */
.gs-imageResult .gs-title,
.gs-imageResult .gs-snippet,
.gs-imageResult .gs-visibleUrl,
.gs-imageResult .gs-visibleUrl-short,
.gs-imageResult .gs-spelling {
  padding: 0;
}

/* Color hover text, but not no results text */
.gs-imageResult:not(.gs-no-results-result) .gs-snippet {
  overflow: hidden;
  white-space: nowrap;
  color: #eee;
}

.gs-imageResult .gs-size {
  display: inline;
}

.gs-imageResult .gs-image-box {
  text-align: center; /* center align image in image box */
}

.gs-imageResult .gs-image-box .gs-image {
  border: none;
}

.gs-image-scalable {
  height: 180px;
}

.gs-selectedImageResult {
  /* 180px (gs-image-scalable height) + 2*5px (gs-image-thumbnail-box padding) +
   * 350px (gs-imagePreviewArea height)
   */
  height: 540px;
}

.gs-imagePreview {
  display: block;
  max-height: 100%;
  max-width: 100%;
}

/* Avoid auto dimensions for SVGs, lest they be hidden */
.gs-imagePreview:not([src$=".svg"]) {
  height: auto;
  width: auto;
}

.gs-imagePreviewArea {
  display: -ms-flexbox;
  display: flex;
  -ms-flex-pack: distribute;
  justify-content: center;
  -ms-flex-align: center;
  align-items: center;
  position: absolute;
  background: #222;
  width: 100%;
  height: 350px;
  left: 0;
  z-index: 100000;
}

.gs-imagePreviewArea-invisible {
  display: none;
}

.gs-previewSnippet {
  margin: 30px;
}

.gs-previewLink {
  color: #eee;
  font-size: 18px;
  text-decoration: none;
}

.gs-imagePreviewArea>.gs-previewLink {
  -ms-flex-align: center;
  align-items: center;
  display: -ms-flexbox;
  display: flex;
  height: 100%;
}

.gs-previewTitle,
.gs-previewUrl,
.gs-previewSize {
  margin: 10px 0;
  color: #eee;
}

.gs-previewDescription {
  margin: 20px 0;
  color: #ccc;
}

/* Popup layout related styles */

.gsc-imageResult .gs-imageResult-popup {
  border: 0;
  margin: 0;
  width: auto; /* Override the default image result width */
  overflow: visible; /* popup box may overflow and should be visible */
  position: relative;
}

/* Instead put margin bottom and right on searcher image thumbnail. */
.gs-imageResult-popup .gs-image-thumbnail-box {
  padding: 5px;
}

.gs-imageResult-popup .gs-image-box {
  width: auto;
}

.gs-imageResult-popup .gs-image-popup-box {
  width: calc(100% - 20px);
  position: absolute;
  padding: 5px;
  margin: 5px;
  left: 0;
  bottom: 0;
  background: rgba(51, 51, 51, 0.8);
  display: none;
}

.gs-imageResult-popup .gs-image-popup-box .gs-image-box {
  display: none;
}

.gs-imageResult-popup .gs-image-popup-box .gs-text-box {
  height: auto;
  width: auto;
}

/* Do not show title for compact layout such as classic and popup */
.gs-imageResult-popup .gs-text-box .gs-title {
  display: none;
}

